<script setup>
import {computed,ref,onMounted} from 'vue'
import {withBase} from 'vitepress'
import data from './consulting.json'
const props=defineProps({page:{type:String,default:'home'}})
const p=computed(()=>data.pages[props.page]||data.pages.home)
const path=withBase
const img=(name)=>path('/images/consulting/'+name)
const dialog=ref(null),expanded=ref(''),expandedAlt=ref('')
function zoom(name,alt){expanded.value=name;expandedAlt.value=alt;dialog.value?.showModal()}
const service=ref(''),goal=ref(''),timing=ref(''),environment=ref(''),status=ref('')
onMounted(()=>{service.value=new URLSearchParams(window.location.search).get('service')||p.value.title})
const draft=computed(()=>['안녕하세요. 피엠오피스 컨설팅을 문의드립니다.','','관심 서비스: '+(service.value||p.value.title),'해결할 과제: '+(goal.value.trim()||'상담 시 논의'),'희망 일정·제출일: '+(timing.value.trim()||'협의'),'필요 산출물·사용 환경: '+(environment.value.trim()||'상담 시 확인'),'','위 내용을 바탕으로 수행 범위와 준비 자료를 안내 부탁드립니다.'].join('\n'))
const mail=computed(()=> 'mailto:'+data.email+'?subject='+encodeURIComponent('[피엠오피스 컨설팅] '+(service.value||p.value.title))+'&body='+encodeURIComponent(draft.value))
async function copy(){try{await navigator.clipboard.writeText(draft.value);status.value='초안을 복사했습니다.'}catch{status.value='아래 초안을 선택해 복사해 주세요.'}}
const groups=[['pm','PM 컨설팅','EPC · R&D · 글로벌 기업','관리 체계와 통합 일정, 실행과 보고를 연결합니다.','original-weight.webp'],['scheduling','공정표 작성 대행','입찰 · 발주처·감독기관 · 기업 통합','제출 목적과 일정의 논리를 갖춘 결과물을 만듭니다.','gantt-screen.webp'],['ai','AI 컨설팅','ChatGPT · Microsoft Copilot','적용 업무를 선정하고 검증과 운영까지 설계합니다.','report-dashboard.webp']]
const screen=(props.page==='pm'?'weight-screen.webp':props.page==='scheduling'?'excel-schedule.webp':'original-weight.webp')
</script>
<template><div class="consulting marketing">
  <section class="consult-hero section-inner">
    <div class="consult-hero-copy"><a v-if="page!=='home'" :href="path('/consulting/')" class="consult-back">← 컨설팅</a><span v-else class="consult-eyebrow">PMOFFICE CONSULTING</span><h1 id="page-title">{{p.title}}</h1><p>{{p.intro}}</p><div class="actions"><a class="btn primary" href="#consulting-inquiry">맞춤 컨설팅 상담 ↗</a><a class="btn secondary" :href="page==='home'?'#services':'#service-details'">서비스 살펴보기 ↓</a></div><div class="consult-hero-tools">Microsoft Project <span>×</span> Excel <span>×</span> AI</div></div>
    <button class="consult-hero-screen" type="button" @click="zoom(p.image,'Microsoft Project 공정표 및 보고서')" aria-label="공정표 및 보고서 화면 확대"><img :src="img(p.image)" alt="Microsoft Project 공정표 및 보고서" fetchpriority="high" width="1144" height="761"><span aria-hidden="true">↗</span></button>
  </section>
  <template v-if="page==='home'">
    <section id="services" class="section-inner consult-services"><div class="consult-heading"><span class="consult-eyebrow">컨설팅 분야</span><h2>필요한 컨설팅 분야를<br>확인하십시오.</h2></div><div class="consult-service-grid"><a v-for="(g,i) in groups" :key="g[0]" :href="path(data.pages[g[0]].path)" class="consult-service"><span class="consult-number">0{{i+1}}</span><h3>{{g[1]}} <span>↗</span></h3><p>{{g[2]}}</p><img :src="img(g[4])" alt="프로젝트 공정표 및 보고 화면" width="1144" height="761" loading="lazy"><strong>{{g[3]}}</strong></a></div></section>
    <section class="consult-proof"><div class="section-inner"><div class="consult-heading"><span class="consult-eyebrow">공정표·진도 관리</span><h2>계획 대비 실적과<br>주공정을 확인하십시오.</h2><p>작업의 연결, 주공정, 기간별 보할과 누적 진도.<br>관리할 정보를 목적에 맞는 공정표와 보고 화면으로 구성합니다.</p></div><div class="consult-screen-pair"><button type="button" @click="zoom('original-gantt.png','공정표와 누적 진도')" aria-label="공정표와 누적 진도 확대"><img :src="img('original-gantt.webp')" alt="공정표와 누적 진도" loading="lazy" width="1076" height="761"><span>↗</span></button><button type="button" @click="zoom('original-weight.png','기간별 보할과 누적 진도')" aria-label="기간별 보할과 누적 진도 확대"><img :src="img('original-weight.webp')" alt="기간별 보할과 누적 진도" loading="lazy" width="1144" height="629"><span>↗</span></button></div></div></section>
  </template>
  <ExperienceProof v-if="['home','pm','scheduling'].includes(page)" />
  <section v-if="p.sections.length" id="service-details" class="section-inner consult-details"><nav v-if="p.sections.length>1" class="consult-jumps" aria-label="컨설팅 분야"><a v-for="s in p.sections" :key="s.id" :href="'#'+s.id">{{s.title}}</a></nav><article v-for="(s,i) in p.sections" :key="s.id" :id="s.id" class="consult-detail"><div class="consult-detail-heading"><span class="consult-number">0{{i+1}}</span><h2>{{s.title}}</h2><p>{{s.lead}}</p></div><div class="consult-detail-content"><div class="consult-work"><div v-for="item in s.items" :key="item.title"><h3>{{item.title}}</h3><p>{{item.text}}</p></div></div><div class="consult-deliver"><h3>제공 산출물</h3><ul><li v-for="item in s.outputs" :key="item">{{item}}</li></ul></div><div class="consult-checks"><details><summary>준비 자료</summary><ul><li v-for="item in s.inputs" :key="item">{{item}}</li></ul></details><details><summary>검수 기준</summary><ul><li v-for="item in s.accept" :key="item">{{item}}</li></ul></details></div><a class="text-link" :href="'?service='+encodeURIComponent(s.title)+'#consulting-inquiry'">{{s.title}} 상담 ↗</a></div></article></section>
  <section v-if="page==='ai'" class="consult-proof"><div class="section-inner"><div class="consult-heading"><span class="consult-eyebrow">AI 업무 적용</span><h2>업무별 AI 적용 과제와<br>운영 기준을 정합니다.</h2></div><div class="consult-ai-fields"><article v-for="(f,i) in data.aiFields" :key="f.title"><span>0{{i+1}}</span><div><h3>{{f.title}}</h3><p>{{f.text}}</p></div></article></div><div class="consult-ai-links"><a :href="path('/consulting/ai/chatgpt.html')"><h3>ChatGPT 컨설팅 ↗</h3><p>프롬프트·자료·분석·문서·팀 업무</p></a><a :href="path('/consulting/ai/copilot.html')"><h3>Microsoft Copilot 컨설팅 ↗</h3><p>Microsoft 365·조직 지식·Copilot Studio</p></a></div></div></section>
  <section v-if="page!=='home'" class="section-inner consult-wide-screen"><button type="button" @click="zoom(screen,'Project 및 Excel 프로젝트 관리 화면')" aria-label="프로젝트 관리 화면 확대"><img :src="img(screen)" alt="Project 및 Excel 프로젝트 관리 화면" loading="lazy" width="1592" height="995"><span>↗</span></button></section>
  <section v-if="page==='pm'" class="section-inner consult-industries"><img :src="img('industries.webp')" alt="EPC·연구개발·글로벌 기업 프로젝트" loading="lazy" width="1536" height="1024"><div><span class="consult-eyebrow">산업별 관리 특성</span><h2>EPC·R&D·글로벌 기업의<br>업무 특성에 맞춰 설계합니다.</h2><p>공통 관리 원칙을 기반으로, 프로젝트의 단계·참여 조직·산출물과 보고 조건을 구체화합니다.</p></div></section>
  <section class="section-inner project-entry"><h2>MS Project가 처음이신가요?</h2><p>일정부터 자원·비용·보고서까지, 화면으로 활용 방법을 살펴보세요.</p><a class="btn secondary" :href="path('/ms-project/introduction.html')">MS Project 소개 ↗</a></section>
  <section class="section-inner consult-process"><div class="consult-heading"><span class="consult-eyebrow">컨설팅 수행 절차</span><h2>진단·작성·검토부터<br>담당자 운영 인계까지 지원합니다.</h2></div><ol><li v-for="(step,i) in data.process" :key="step[0]"><span>0{{i+1}}</span><h3>{{step[0]}}</h3><p>{{step[1]}}</p></li></ol></section>
  <section id="membership" class="consult-membership"><div class="section-inner"><span class="consult-eyebrow">평생 지식 공유 멤버십</span><h2>{{data.membership.title}}</h2><p class="consult-member-lead">{{data.membership.lead}}</p><div class="consult-member-grid"><article v-for="(m,i) in data.membership.items" :key="m.title"><span>0{{i+1}}</span><h3>{{m.title}}</h3><p>{{m.text}}</p></article></div><p class="consult-member-terms">{{data.membership.terms}}</p><a :href="path('/knowledge/index.html')" class="text-link">지식 공간 살펴보기 ↗</a></div></section>
  <section class="section-inner consult-faq"><div class="consult-heading"><span class="consult-eyebrow">FAQ</span><h2>상담 전, 궁금한 점</h2></div><details v-for="f in p.faq" :key="f.q"><summary>{{f.q}}</summary><p>{{f.a}}</p></details></section>
  <section id="consulting-inquiry" class="consult-inquiry"><div class="section-inner"><div class="consult-heading"><span class="consult-eyebrow">컨설팅 문의</span><h2>관리 대상 사업과<br>필요한 산출물을 알려주십시오.</h2><p>현재 자료와 필요한 결과물을 알려주시면,<br>수행 범위와 준비 사항을 구체적으로 논의합니다.</p></div><div class="consult-form-layout"><div class="consult-form"><label>관심 서비스<select v-model="service" aria-label="관심 서비스"><option v-for="o in [...new Set([p.title,service,'MS Project 교육','AI 교육','PM 컨설팅','EPC 프로젝트 관리 컨설팅','연구개발 사업 관리 컨설팅','글로벌 기업 프로젝트','입찰 제출용 공정표 작성 대행','발주처·감독기관 제출용 공정표 작성 대행','기업 맞춤형 통합 관리 공정표','AI 컨설팅','ChatGPT 컨설팅','Microsoft Copilot 컨설팅'])].filter(Boolean)" :key="o">{{o}}</option></select></label><label>해결할 과제<textarea v-model="goal" rows="3" maxlength="800" placeholder="관리할 프로젝트와 필요한 지원을 알려주세요."></textarea></label><label>희망 일정·제출일<input v-model="timing" maxlength="180" placeholder="정해지지 않았다면 비워두셔도 됩니다."></label><label>필요 산출물·사용 환경<input v-model="environment" maxlength="250" placeholder="예: MS Project·Excel 공정표, 발주처 제출용 PDF"></label></div><div class="consult-draft"><h3>문의 초안</h3><textarea :value="draft" readonly rows="12" aria-label="문의 초안"></textarea><div class="actions"><a class="btn primary" :href="mail">메일 앱에서 보내기 ↗</a><button class="btn secondary" type="button" @click="copy">초안 복사</button></div><p class="consult-status" role="status">{{status}}</p><div class="consult-direct"><a :href="'mailto:'+data.email">{{data.email}}</a><a href="tel:025328060">{{data.phone}}</a></div></div></div></div></section>
  <section class="section-inner consult-related"><h2>관련 교육과 실무 지식</h2><a :href="path('/ms-project/')">Microsoft Project 교육 ↗</a><a :href="path('/pm-practice/')">프로젝트 관리 실무 ↗</a><a :href="path('/ai-edu/')">AI 교육 ↗</a><a :href="path('/knowledge/index.html')">지식 공간 ↗</a></section>
  <footer class="marketing-footer section-inner"><a class="footer-brand" :href="path('/')">PMOffice<span>피엠오피스</span></a><div><a :href="path('/about.html')">소개</a><a :href="path('/consulting/')">컨설팅</a><a :href="path('/ai-edu/')">AI 교육</a><a :href="path('/contact.html')">문의</a></div><p>© {{new Date().getFullYear()}} PMOffice</p></footer>
  <dialog ref="dialog" class="consult-image-dialog" :aria-label="expandedAlt" @click="e=>{if(e.target===dialog)dialog.close()}"><button class="consult-dialog-close" type="button" @click="dialog.close()" aria-label="화면 확대 닫기">닫기 ×</button><div><img v-if="expanded" :src="img(expanded)" :alt="expandedAlt"></div></dialog>
</div></template>
